from fastapi import FastAPI, Form, HTTPException
from fastapi.testclient import TestClient
from typing import Optional

app = FastAPI()

@app.post("/test_optional")
async def test_optional_endpoint(q: Optional[str] = Form(None)):
    return {"q": q}

@app.post("/test_required")
async def test_required_endpoint(q: str = Form(...)):
    return {"q": q}

client = TestClient(app)

def test_optional_empty_string():
    response = client.post("/test_optional", data={"q": ""})
    print(f"Optional empty string: {response.json()}")
    assert response.json()["q"] is None

def test_required_empty_string():
    response = client.post("/test_required", data={"q": ""})
    print(f"Required empty string: {response.json()}")
    assert response.json()["q"] == ""

def test_required_missing():
    response = client.post("/test_required", data={})
    print(f"Required missing: {response.status_code}")
    assert response.status_code == 422

if __name__ == "__main__":
    try:
        test_optional_empty_string()
        test_required_empty_string()
        test_required_missing()
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
